// Lookup function for use in screening
function getMarketBenchmark(searchId) {
  return MARKET_BENCHMARKS_DATA[searchId] || {name:'Unknown', avgADR:{2:200,3:250,4:300,5:350,6:400}, avgOccupancy:0.55, avgCleaningFee:{2:100,3:125,4:150,5:175,6:200}};
}

function estimateRevenue(searchId, beds) {
  const bm = getMarketBenchmark(searchId);
  const bedKey = Math.min(Math.max(beds, 2), 6);
  const adr = bm.avgADR[bedKey] || 250;
  const gross = Math.round(adr * 365 * bm.avgOccupancy);
  return { adr, occ: bm.avgOccupancy, gross, cleaningFee: bm.avgCleaningFee[bedKey] || 150 };
}

function classifySeedDeal(gross, listPrice) {
  const ratio = listPrice > 0 ? gross / listPrice : 0;
  if (ratio >= 0.20) return { tier: 'good', ratio, targetOffer: null };
  if (ratio >= 0.15) {
    const target = Math.ceil(gross / 0.20 / 1000) * 1000;
    return { tier: 'needs_offer', ratio, targetOffer: target };
  }
  return { tier: 'dq', ratio, targetOffer: null };
}

